  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\nenum DataSourceType {\n  PWA_DIRECT_USER\n  RISKESDAS_KEMENKES\n  SURVEY_CSV_UPLOAD\n  EXTERNAL_HEALTH_API\n}\n\n/// Daftar kelurahan Kota Bontang (15 kelurahan riil) — dipakai sebagai lookup\n/// relasional pengganti string bebas. Screening dari luar Bontang (atau data\n/// riset nasional seperti Riskesdas) TIDAK punya baris di sini — lihat\n/// `ScreeningRecord.externalLocationLabel`.\nmodel Kelurahan {\n  id         String            @id @default(uuid())\n  name       String            @unique\n  district   String // Kecamatan: Bontang Utara/Selatan/Barat\n  createdAt  DateTime          @default(now())\n  screenings ScreeningRecord[]\n}\n\n/// Identitas anonim per perangkat/browser (UUID di localStorage, TANPA\n/// login/password — sesuai prinsip Zero-Login Friction PRD). Satu sesi bisa\n/// memiliki banyak ScreeningRecord dari waktu ke waktu (mis. orang tua yang\n/// sama mengukur ulang balitanya tiap bulan). `persona` di sini adalah nilai\n/// TERKINI/TERAKHIR sesi tsb — nilai persona pada saat submission tertentu\n/// tetap tersimpan apa adanya di `ScreeningRecord.persona` masing-masing.\nmodel AnonymousSession {\n  id          String            @id @default(uuid())\n  clientToken String            @unique\n  persona     String            @default(\"Orang Tua / Anggota Keluarga Balita\")\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n  screenings  ScreeningRecord[]\n\n  @@index([clientToken])\n}\n\n/// Log audit tiap batch impor (CSV/Riskesdas). `id` DISUPLAI APLIKASI (bukan\n/// auto-generate) — nilainya sama persis dengan `ScreeningRecord.sourceBatchId`\n/// milik baris-baris hasil batch tsb, sehingga relasinya nyata & bisa di-JOIN\n/// (sebelum revisi ini, keduanya adalah dua ID acak terpisah yang tidak pernah\n/// benar-benar berhubungan — bug yang diperbaiki di sini).\nmodel IngestionBatchLog {\n  id           String            @id\n  sourceName   String\n  sourceType   DataSourceType\n  totalRecords Int\n  successCount Int\n  failedCount  Int\n  importedAt   DateTime          @default(now())\n  screenings   ScreeningRecord[]\n}\n\n/// Entitas INTI satu kali skrining: identitas, lokasi, dan antropometri\n/// mentah (input pengguna). Hasil hitung WHO, jawaban kuesioner determinan,\n/// dan skor risiko sengaja DIPISAH ke tabel anak 1:1 (`GrowthAssessment`,\n/// `ScreeningDeterminants`, `RiskAssessment`) supaya tabel ini tetap ramping\n/// dan gampang dibaca walau datanya nanti jadi ratusan ribu baris. Endpoint\n/// API tetap mengembalikan gabungan semua tabel ini sebagai satu objek datar\n/// (lihat VIEW `screening_record_flat`) — kontrak frontend tidak berubah.\nmodel ScreeningRecord {\n  id            String             @id @default(uuid())\n  shareHash     String             @unique @default(nanoid(10))\n  sessionId     String\n  session       AnonymousSession   @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  sourceType    DataSourceType     @default(PWA_DIRECT_USER)\n  sourceBatchId String?\n  batch         IngestionBatchLog? @relation(fields: [sourceBatchId], references: [id])\n\n  /// Peran pengisi PADA SAAT submission ini (lihat catatan di AnonymousSession\n  /// soal kenapa ini tidak selalu sama dengan AnonymousSession.persona).\n  /// Dikunci CHECK constraint di level DB (lihat migration) ke 4 nilai resmi.\n  persona String\n\n  kelurahanId           String?\n  kelurahan             Kelurahan? @relation(fields: [kelurahanId], references: [id])\n  /// Dipakai saat isOutsideBontang=true ATAU data eksternal (mis. Riskesdas\n  /// nasional) — kelurahanId dibiarkan null, label bebas disimpan di sini.\n  externalLocationLabel String?\n  isOutsideBontang      Boolean\n\n  ageMonths Int\n  /// Dikunci CHECK constraint ke 'Laki-Laki' | 'Perempuan' (lihat migration).\n  gender    String\n  weightKg  Float\n  heightCm  Float\n\n  createdAt DateTime @default(now())\n\n  growth       GrowthAssessment?\n  determinants ScreeningDeterminants?\n  risk         RiskAssessment?\n\n  @@index([sessionId])\n  @@index([shareHash])\n  @@index([kelurahanId])\n}\n\n/// Hasil hitung Z-Score WHO 2006 (OUTPUT turunan, bukan input) — dipisah dari\n/// ScreeningRecord karena ini nilai yang DIHITUNG mesin (zscoreEngine), bukan\n/// dikumpulkan langsung dari pengguna.\nmodel GrowthAssessment {\n  screeningRecordId String          @id\n  screening         ScreeningRecord @relation(fields: [screeningRecordId], references: [id], onDelete: Cascade)\n\n  zScore    Float // Z-Score TB/U (Height-for-Age)\n  zScoreWAZ Float? // Z-Score BB/U (Weight-for-Age)\n  zScoreWHZ Float? // Z-Score BB/TB (Weight-for-Height)\n\n  statusGiziTBU  String? // Sangat Pendek | Pendek | Normal | Tinggi\n  statusGiziBBU  String? // Severely Underweight | Underweight | Normal | Risiko BB Lebih\n  statusGiziBBTB String? // Severely Wasted | Wasted | Normal | Overweight/Obesitas\n}\n\n/// Jawaban mentah 11 pertanyaan kuesioner determinan lingkungan/pola asuh —\n/// input pengguna, dipisah dari hasil komputasi supaya jelas mana data yang\n/// \"diisi orang\" vs \"dihitung mesin\".\nmodel ScreeningDeterminants {\n  screeningRecordId String          @id\n  screening         ScreeningRecord @relation(fields: [screeningRecordId], references: [id], onDelete: Cascade)\n\n  bblrOption       Int // 1=Normal(>=2500g) 2=BBLR(<2500g) 3=Tidak Tahu\n  exclusiveAsi     Int // 1=Eksklusif 2=Tidak/Formula 3=Belum 6 Bulan\n  mpasiAge         Int // 1=<6Bln(Dini) 2=Tepat 6Bln 3=>6Bln(Terlambat) 4=Belum MPASI\n  animalProtein    Int[] // [1=Ikan 2=Telur 3=Daging 4=Susu 5=Sangat Jarang]\n  cleanWaterAccess Int // 1=Kemasan 2=PDAM 3=Sumur Bor 4=Sumur Gali/Mata Air/Hujan\n  sanitationAccess Int // 1=Milik Sendiri 2=Cemplung 3=MCK 4=Tidak Memiliki\n  smokeExposure    Int // 1=Bebas 2=Terpapar\n  motherEducation  Int // 1=SD 2=SMP 3=SMA/SMK 4=Diploma/Sarjana\n  economicQuintile Int // 1-5 (1=termiskin)\n  diarrheaHistory  Int // 1=Tidak Pernah/1x Ringan 2=Sering/Berulang(>=2x)\n  posyanduKia      Int // 1=Rutin+KIA 2=Kadang-kadang 3=Tidak Pernah/Jarang\n}\n\n/// Output mesin skor risiko (weightedRiskEngine — lihat FDD §6). `engineVersion`\n/// mencatat versi algoritma yang menghasilkan baris ini, supaya kalau\n/// metodologinya berubah lagi di masa depan (sudah pernah terjadi sekali:\n/// Naive Bayes -> weighted-rule), data lama tetap bisa ditelusuri asalnya.\nmodel RiskAssessment {\n  screeningRecordId String          @id\n  screening         ScreeningRecord @relation(fields: [screeningRecordId], references: [id], onDelete: Cascade)\n\n  riskTier        String // LOW | MODERATE | HIGH\n  riskScore       Float // 0.0 - 1.0\n  dominantFactors String[]\n  rawMetadata     Json?\n  engineVersion   String   @default(\"weighted-v1\")\n\n  @@index([riskTier])\n}\n\n/// Konten edukasi statis (pedoman gizi/kesehatan) — SENGAJA berdiri sendiri\n/// tanpa relasi ke ScreeningRecord manapun. Ini tabel referensi/konten\n/// (seperti CMS), bukan data transaksional per-anak; chat controller memilih\n/// baris yang relevan secara dinamis berdasarkan riskTier & rentang umur saat\n/// itu, bukan lewat foreign key permanen.\nmodel HealthKnowledgeBase {\n  id                      String   @id @default(uuid())\n  topicTitle              String\n  category                String\n  targetAgeGroupMinMonths Int      @default(0)\n  targetAgeGroupMaxMonths Int      @default(59)\n  targetRiskTier          String\n  tags                    String[]\n  guidelineContent        String   @db.Text\n  actionableSteps         String[]\n  sourceReference         String\n  createdAt               DateTime @default(now())\n\n  @@index([category])\n  @@index([targetRiskTier])\n}\n",
